import csv, io
from dataclasses import dataclass, field, replace
from .errors import ImportFileError, ValidationError
from .models import Contact
from .validation import normalize_email, normalize_phone, normalize_tags, validate_name

@dataclass
class RowIssue:
    row: int
    column: str | None
    message: str

@dataclass
class ImportReport:
    created: list = field(default_factory=list)
    updated: list = field(default_factory=list)
    errors: list = field(default_factory=list)
    warnings: list = field(default_factory=list)

KNOWN = ("name", "email", "phone", "tags", "first_name", "last_name")

def import_contacts(repo, data):
    if isinstance(data, bytes):
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError:
            raise ImportFileError('re-save the file as "CSV UTF-8"') from None
    elif isinstance(data, str):
        text = data
    else:
        raise TypeError("data must be str or bytes")
    if text.startswith("﻿"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    rows = []
    start = 1
    for cells in reader:
        rows.append((start, cells))
        start = reader.line_num + 1
    blank = lambda c: all(not x.strip() for x in c)
    if not rows or blank(rows[0][1]):
        raise ImportFileError("empty")
    header = [h.strip().lower() for h in rows[0][1]]
    raw = rows[0][1]
    for k in KNOWN:
        if header.count(k) > 1:
            raise ImportFileError("dup " + k)
    if "email" not in header:
        raise ImportFileError("no email")
    if "name" in header:
        used = {"name", "email", "phone", "tags"}
    elif "first_name" in header and "last_name" in header:
        used = {"first_name", "last_name", "email", "phone", "tags"}
    else:
        raise ImportFileError("no name")
    report = ImportReport()
    for i, h in enumerate(header):
        if h not in used:
            report.warnings.append(RowIssue(1, None, f"unknown column {raw[i]!r} ignored"))
    body = [(n, c) for n, c in rows[1:] if not blank(c)]
    if len(body) > 1000:
        raise ImportFileError("too many")
    idx = {h: i for i, h in enumerate(header)}
    pending = {}
    order = []
    claimed = set()
    for n, cells in body:
        if len(cells) > len(header):
            report.errors.append(RowIssue(n, None, "too many cells")); continue
        cells = cells + [""] * (len(header) - len(cells))
        get = lambda k: cells[idx[k]] if k in idx else ""
        try:
            if "name" in used:
                name = validate_name(get("name"))
            else:
                parts = [p for p in (get("first_name").strip(), get("last_name").strip()) if p]
                name = validate_name(" ".join(parts))
            email = normalize_email(get("email"))
            tags = normalize_tags([p for p in get("tags").split(";") if p.strip()])
        except ValidationError as e:
            report.errors.append(RowIssue(n, e.field, e.message)); continue
        if email in claimed:
            report.errors.append(RowIssue(n, "email", "duplicate")); continue
        phone = None
        if get("phone").strip():
            try:
                phone = normalize_phone(get("phone"))
            except ValidationError as e:
                report.warnings.append(RowIssue(n, "phone", e.message))
        claimed.add(email)
        old = repo.find(email)
        if old is None:
            pending[email] = ("add", Contact(name, email, phone, tags)); report.created.append(email)
        else:
            new = replace(old, name=name, phone=phone or old.phone, tags=old.tags | tags)
            if new != old:
                pending[email] = ("upd", new); report.updated.append(email)
    for op, c in pending.values():
        (repo.add if op == "add" else repo.update)(c)
    return report
